import React from 'react'
import ReactApexChart from 'react-apexcharts'
import './styles.css'

const ApexChart = () => {
  const [state, setState] = React.useState({
    series: [
      { name: 'A', data: [1] },
      { name: 'B', data: [3] },
      { name: 'C', data: [3] },
    ],
    options: {
      chart: {
        type: 'bar',
        height: 200,
        stacked: true,
        stackType: '100%',
      },
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 10,
          barHeight: '100%',
        },
      },
      colors: ['#008FFB', '#00E396', '#FEB019'],
      dataLabels: {
        enabled: false,
      },
      stroke: {
        width: 1,
        colors: ['#fff'],
      },
      title: {
        text: 'single-point horizontal stack: outer ends round, inner joins square (#4845)',
        style: { fontSize: '13px', fontWeight: 500 },
      },
      xaxis: {
        categories: ['Total'],
      },
      legend: {
        position: 'top',
      },
    },
  })

  return (
    <div>
      <div id="chart">
        <ReactApexChart
          options={state.options}
          series={state.series}
          type="bar"
          height={200}
        />
      </div>
    </div>
  )
}

export default ApexChart
